@Test
public void testPlusDaysNegative() throws Exception {
    LocalDate base = new LocalDate(2020, 1, 1);
    LocalDate result = base.plusDays(-5);
    assertEquals("2019-12-27", result.toString());
}

@Test
public void testPlusDaysMaxPositive() throws Exception {
    LocalDate base = new LocalDate(2020, 1, 1);
    LocalDate result = base.plusDays(365);
    assertEquals("2021-01-01", result.toString());
}

@Test
public void testPlusDaysMinNegative() throws Exception {
    LocalDate base = new LocalDate(2020, 1, 1);
    LocalDate result = base.plusDays(-365);
    assertEquals("1919-01-01", result.toString());
}

@Test
public void testPlusDaysBoundaryStartOfYear() throws Exception {
    LocalDate base = new LocalDate(2020, 1, 1);
    LocalDate result = base.plusDays(-1);
    assertEquals("1919-12-31", result.toString());
}

@Test
public void testPlusDaysBoundaryEndOfYear() throws Exception {
    LocalDate base = new LocalDate(2020, 12, 31);
    LocalDate result = base.plusDays(1);
    assertEquals("2021-01-01", result.toString());
}

@Test
public void testPlusDaysLeapYear() throws Exception {
    LocalDate base = new LocalDate(2020, 2, 29);
    LocalDate result = base.plusDays(1);
    assertEquals("2020-03-01", result.toString());
}

@Test
public void testPlusDaysNonLeapYear() throws Exception {
    LocalDate base = new LocalDate(2021, 2, 28);
    LocalDate result = base.plusDays(1);
    assertEquals("2021-03-01", result.toString());
}
